-- Table: accounting_expense
-- Source: accounting_admin_db.sql (6. Accounting expense, reconciliation, and period closing)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS accounting_expense (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    document_number    VARCHAR(50) NOT NULL UNIQUE,
    document_date      DATE NOT NULL,
    expense_type       VARCHAR(30) NOT NULL
                       CHECK (expense_type IN ('salary', 'purchase', 'office_supplies', 'utilities', 'logistics', 'maintenance', 'travel', 'other')),
    category           VARCHAR(100),
    department_id      BIGINT REFERENCES masterdata_department(id),
    cost_center_id     BIGINT REFERENCES masterdata_cost_center(id),
    budget_plan_id     BIGINT REFERENCES budget_plan(id),
    budget_allocation_id BIGINT REFERENCES budget_allocation(id),
    employee_id        BIGINT REFERENCES masterdata_employee(id),
    supplier_id        BIGINT REFERENCES masterdata_supplier(id),
    paid_to            VARCHAR(150),
    payment_method     VARCHAR(20) NOT NULL DEFAULT 'transfer'
                       CHECK (payment_method IN ('cash', 'transfer', 'check')),
    bank_account_id    BIGINT REFERENCES masterdata_bank_account(id),
    description        TEXT,
    subtotal           NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (subtotal >= 0),
    tax_amount         NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0),
    grand_total        NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (grand_total >= 0),
    status             VARCHAR(20) NOT NULL DEFAULT 'draft'
                       CHECK (status IN ('draft', 'created', 'approved', 'rejected', 'pending', 'completed', 'reopen')),
    attachment_url     TEXT,
    notes              TEXT,
    submitted_by       BIGINT REFERENCES masterdata_user(id),
    approved_by        BIGINT REFERENCES masterdata_user(id),
    approved_at        TIMESTAMPTZ,
    posted_by          BIGINT REFERENCES masterdata_user(id),
    posted_at          TIMESTAMPTZ,
    journal_id         BIGINT REFERENCES accounting_journal(id),
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
